package io.github.miklires.mevents;
import io.github.miklires.mevents.command.EventCommand;import io.github.miklires.mevents.event.*;import io.github.miklires.mevents.storage.EventRepository;import org.bstats.bukkit.Metrics;import org.bukkit.command.PluginCommand;import org.bukkit.plugin.ServicePriority;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;
public final class MEventsPlugin extends JavaPlugin{private EventRepository repository;private EventCatalog catalog;private EventService service;@Override public void onEnable(){saveResource("events.yml",false);catalog=new EventCatalog();reloadCatalog();repository=new EventRepository(getDataFolder().toPath().resolve("events"));service=new EventService(this,catalog,repository);repository.initialize().thenCompose(ignored->repository.cancelOrphans()).thenAccept(count->{getLogger().info("Reconciled "+count+" unfinished event(s).");service.retryPending();}).exceptionally(error->{getLogger().severe("Database initialization failed: "+error.getMessage());getServer().getPluginManager().disablePlugin(this);return null;});getServer().getPluginManager().registerEvents(new EventListener(service),this);PluginCommand command=getCommand("event");if(command==null)throw new IllegalStateException("event command missing");EventCommand handler=new EventCommand(service,this::reloadCatalog);command.setExecutor(handler);command.setTabCompleter(handler);getServer().getServicesManager().register(io.github.miklires.mevents.api.MEventsApi.class,service,this,ServicePriority.Normal);new Metrics(this,27941);getLogger().info("mEvents 1.0.0 enabled.");}@Override public void onDisable(){if(service!=null)service.shutdown();if(repository!=null)repository.close();}private void reloadCatalog(){catalog.load(new File(getDataFolder(),"events.yml"));}}
